{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = 0
    cap_sum = 0
    for seg in segments:
        min_sum += seg['minimum']
        cap_sum += seg['capacity']
    if budget < min_sum or budget > cap_sum:
        raise ValueError("Budget infeasible")
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = None
        best_val = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] < seg['capacity']:
                val = seg['importance'] / (alloc[i] + 1)
                if val > best_val:
                    best_val = val
                    best_idx = i
        alloc[best_idx] += 1
        remaining -= 1
    total = sum(alloc)
    by_name = {}
    for seg, a in zip(segments, alloc):
        by_name[seg['name']] = a
    return {"allocations": alloc, "by_name": by_name, "total": total}
"}
